// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap at a
// given instant, not WHICH face was hit. Discrete overlap alone can miss a
// fast ball that tunnels through (see #1), so `brickHit` also sweeps between
// the previous and current positions (below).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// True if the ball's swept path from (px, py) to (x, y) touches the brick.
// This closes the tunnelling gap: a stuttered frame at a high level moves the
// ball more than a brick is thick, so a discrete test alone would let it jump
// straight through. `brickHit` relies on it after `step()` records px/py.
function sweepHits(ball, brick) {
  const dx = ball.x - ball.px;
  const dy = ball.y - ball.py;
  const dist = Math.hypot(dx, dy);
  if (dist === 0) return false;

  // Sample the path finely enough that a brick (thinner than the gap) can never
  // slip between two consecutive samples.
  const stepLen = Math.min(4, Math.min(brick.w, brick.h) * 0.25);
  const steps = Math.max(1, Math.ceil(dist / stepLen));
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const sx = ball.px + dx * t;
    const sy = ball.py + dy * t;
    if (
      sx + ball.r > brick.x &&
      sx - ball.r < brick.x + brick.w &&
      sy + ball.r > brick.y &&
      sy - ball.r < brick.y + brick.h
    ) {
      return true;
    }
  }
  return false;
}

// Classify which face(s) of `brick` the ball hit, and how to push the ball back
// out of it. `direct` is true when the ball currently overlaps the brick (so we
// can read the penetration); when false the ball tunnelled past it and we fall
// back to its direction of travel.
function resolveFace(ball, brick, direct) {
  const r = ball.r;
  const left = brick.x;
  const right = brick.x + brick.w;
  const top = brick.y;
  const bottom = brick.y + brick.h;

  if (direct) {
    // Penetration depth through each of the four faces.
    const fromLeft = ball.x + r - left;
    const fromRight = right - (ball.x - r);
    const fromTop = ball.y + r - top;
    const fromBottom = bottom - (ball.y - r);

    const minX = Math.min(fromLeft, fromRight);
    const minY = Math.min(fromTop, fromBottom);

    if (minX + 0.0001 < minY) {
      // Side hit: flip only vx, push out along x.
      return {
        flipVX: true,
        flipVY: false,
        pushX: fromLeft <= fromRight ? left - r - ball.x : right + r - ball.x,
        pushY: 0,
      };
    }
    if (minY + 0.0001 < minX) {
      // Top/bottom hit: flip only vy, push out along y.
      return {
        flipVX: false,
        flipVY: true,
        pushX: 0,
        pushY: fromTop <= fromBottom ? top - r - ball.y : bottom + r - ball.y,
      };
    }
    // Corner: penetrations are (roughly) equal -> flip both axes and push out
    // along both in the direction of travel so the ball escapes the corner.
    const pushX = ball.vx >= 0 ? left - r - ball.x : right + r - ball.x;
    const pushY = ball.vy >= 0 ? top - r - ball.y : bottom + r - ball.y;
    return { flipVX: true, flipVY: true, pushX, pushY };
  }

  // Tunnelled: ball is already past the brick, so classify by travel direction.
  const ax = Math.abs(ball.vx);
  const ay = Math.abs(ball.vy);
  if (ax >= ay) {
    return {
      flipVX: true,
      flipVY: false,
      pushX: ball.vx >= 0 ? left - r - ball.x : right + r - ball.x,
      pushY: 0,
    };
  }
  return {
    flipVX: false,
    flipVY: true,
    pushX: 0,
    pushY: ball.vy >= 0 ? top - r - ball.y : bottom + r - ball.y,
  };
}

// Pure brick-collision resolver: marks every hit brick dead, deflects the ball
// and pushes it back out so it can't stick. Returns `true` if any brick was hit.
//
// The flips are OR-ed across all hit bricks in the same pass: a ball straddling
// the seam between two neighbours (the 8px gap vs a 14px ball) would otherwise
// have its velocity flipped twice and cancel out, plowing straight through (see
// #1). The push-out is applied once, after every brick has been classified.
export function brickHit(ball, bricks) {
  let flipVX = false;
  let flipVY = false;
  let pushX = 0;
  let pushY = 0;
  let hit = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const direct = collides(ball, brick);
    if (!direct && !sweepHits(ball, brick)) continue;

    hit = true;
    brick.alive = false;

    const face = resolveFace(ball, brick, direct);
    flipVX = flipVX || face.flipVX;
    flipVY = flipVY || face.flipVY;
    pushX += face.pushX;
    pushY += face.pushY;
  }

  if (!hit) return false;

  if (flipVX) ball.vx = -ball.vx;
  if (flipVY) ball.vy = -ball.vy;
  ball.x += pushX;
  ball.y += pushY;
  return true;
}

