// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

edits.newText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap at a
// single instant, not WHICH face was hit. A discrete test alone can miss a
// fast ball that tunnels through a brick, so `brickHit` also sweeps between
// the previous and current positions (see #1, sweepHits below).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// True if the ball's swept path from (px, py) to (x, y) touches `brick`. This
// closes the tunnelling gap: a stuttered frame at a high level moves the ball
// further than a brick is thick (35.5 px vs 34 px at level 6), so a discrete
// test alone would let it jump clean through. `step()` records px/py before it
// moves the ball, so `frame()` can sweep afterwards.
function sweepHits(ball, brick) {
  const dx = ball.x - ball.px;
  const dy = ball.y - ball.py;
  const dist = Math.hypot(dx, dy);
  if (dist === 0) return false;

  // Sample the path finely enough that a brick can never slip between two
  // consecutive samples (never more than ~4 px apart).
  const stepLen = Math.min(4, Math.min(brick.w, brick.h) * 0.25);
  const steps = Math.max(1, Math.ceil(dist / stepLen));
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const sx = ball.px + dx * t;
    const sy = ball.py + dy * t;
    if (
      sx + ball.r > brick.x &&
      sx - ball.r < brick.x + brick.w &&
      sy + ball.r > brick.y &&
      sy - ball.r < brick.y + brick.h
    ) {
      return true;
    }
  }
  return false;
}

// Classify which face(s) of `brick` the ball hit, and how to push it back out.
// `direct` is true when the ball currently overlaps the brick, so the smallest
// penetration depth picks the face (see #1). When it tunnelled past (swept
// only) we fall back to the ball's direction of travel.
function resolveFace(ball, brick, direct) {
  const r = ball.r;
  const left = brick.x;
  const right = brick.x + brick.w;
  const top = brick.y;
  const bottom = brick.y + brick.h;

  if (direct) {
    const fromLeft = ball.x + r - left;
    const fromRight = right - (ball.x - r);
    const fromTop = ball.y + r - top;
    const fromBottom = bottom - (ball.y - r);

    const minX = Math.min(fromLeft, fromRight);
    const minY = Math.min(fromTop, fromBottom);

    if (minX + 0.0001 < minY) {
      // Side hit: flip only vx, push out along x.
      return {
        flipVX: true,
        flipVY: false,
        pushX: fromLeft <= fromRight ? left - r - ball.x : right + r - ball.x,
        pushY: 0,
      };
    }
    if (minY + 0.0001 < minX) {
      // Top/bottom hit: flip only vy, push out along y.
      return {
        flipVX: false,
        flipVY: true,
        pushX: 0,
        pushY: fromTop <= fromBottom ? top - r - ball.y : bottom + r - ball.y,
      };
    }
    // Corner: penetrations are (nearly) equal -> flip both axes and push out
    // along both in the direction of travel so the ball escapes the corner.
    return {
      flipVX: true,
      flipVY: true,
      pushX: ball.vx >= 0 ? left - r - ball.x : right + r - ball.x,
      pushY: ball.vy >= 0 ? top - r - ball.y : bottom + r - ball.y,
    };
  }

  // Tunnelled: the ball is already past the brick, classify by travel.
  if (Math.abs(ball.vx) >= Math.abs(ball.vy)) {
    return {
      flipVX: true,
      flipVY: false,
      pushX: ball.vx >= 0 ? left - r - ball.x : right + r - ball.x,
      pushY: 0,
    };
  }
  return {
    flipVX: false,
    flipVY: true,
    pushX: 0,
    pushY: ball.vy >= 0 ? top - r - ball.y : bottom + r - ball.y,
  };
}

// Pure brick-collision resolver (see #1, #2): marks each hit brick dead,
// deflects the ball per face and pushes it back out so it can't stick. Returns
// the list of bricks destroyed this call (empty array when none), which the
// render loop uses to credit score and combo.
//
// The velocity flips are OR-ed across every brick hit in the same pass: a ball
// straddling the seam between two neighbours (8 px gap vs a 14 px ball) would
// otherwise have its velocity flipped twice and cancel, plowing straight
// through instead of bouncing back.
export function brickHit(ball, bricks) {
  let flipVX = false;
  let flipVY = false;
  let pushX = 0;
  let pushY = 0;
  const destroyed = [];

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const direct = collides(ball, brick);
    if (!direct && !sweepHits(ball, brick)) continue;

    brick.alive = false;
    destroyed.push(brick);

    const face = resolveFace(ball, brick, direct);
    flipVX = flipVX || face.flipVX;
    flipVY = flipVY || face.flipVY;
    pushX += face.pushX;
    pushY += face.pushY;
  }

  if (destroyed.length === 0) return destroyed;

  if (flipVX) ball.vx = -ball.vx;
  if (flipVY) ball.vy = -ball.vy;
  ball.x += pushX;
  ball.y += pushY;
  return destroyed;
}

